template <

    class T,

    class Allocator = std::allocator<T>

    >
class forward_list;

namespace pmr {

template <class T>

using forward_list = std::forward_list<T, std::pmr::polymorphic_allocator<T>>;

}

examples.code:
#include <forward_list>
#include <cassert>
#include <iostream>

int main() {
    std::forward_list<int> values{2, 3};
    values.emplace_front(1);
    assert(values.front() == 1);
    auto before = values.before_begin();
    values.insert_after(before, 0);
    assert(values.front() == 0);
    auto allocator = values.get_allocator();
    assert(allocator == values.get_allocator());
    // All elements and their storage are released when values leaves this scope.
    std::cout << "Checks passed\n";
}
